const initial={tasks:[{id:1,title:'Confirm expense categories and approval rules',owner:'Finance',priority:'High',due:'2026-11-12',status:'done'},{id:2,title:'Design receipt submission form',owner:'Aliza',priority:'High',due:'2026-11-14',status:'progress'},{id:3,title:'Build structured expense sheet',owner:'Aliza',priority:'High',due:'2026-11-16',status:'sprint'},{id:4,title:'Write Apps Script automation',owner:'Developer',priority:'Medium',due:'2026-11-20',status:'sprint'},{id:5,title:'Test duplicate receipt checks',owner:'Finance',priority:'Medium',due:'2026-11-23',status:'backlog'},{id:6,title:'Prepare user guide and launch demo',owner:'Aliza',priority:'Low',due:'2026-11-28',status:'backlog'}],risks:[{type:'Risk',description:'Incomplete receipt information delays reconciliation',owner:'Aliza',score:12,response:'Require mandatory fields and validation',status:'Open'},{type:'Risk',description:'Users continue sending receipts through chat',owner:'Founder',score:8,response:'Announce one approved submission channel',status:'Open'},{type:'Issue',description:'Category names differ between Sheet and Oracle',owner:'Finance',score:16,response:'Approve and lock a shared category list',status:'In progress'}],budget:[{name:'Workflow design',base:45000,actual:42000},{name:'Apps Script development',base:90000,actual:68000},{name:'Testing and quality review',base:55000,actual:28000},{name:'Training and documentation',base:35000,actual:12000},{name:'Contingency',base:25000,actual:0}],changes:[{id:1,title:'Add automatic currency conversion',reason:'Founder wants one reporting currency for international travel.',cost:18000,schedule:'+ 1 week',status:'Pending'}],actions:[{text:'Approve final category list',owner:'Finance',due:'12 Nov',status:'Open'},{text:'Share pilot-user names',owner:'Founder',due:'13 Nov',status:'Done'},{text:'Prepare test receipts',owner:'Aliza',due:'14 Nov',status:'Open'}]};
let state=JSON.parse(localStorage.getItem('pm-lab-state')||'null')||structuredClone(initial);const money=n=>'PKR '+Number(n).toLocaleString();const save=()=>{localStorage.setItem('pm-lab-state',JSON.stringify(state));renderAll()};
function toast(m){const t=document.querySelector('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav-item,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('#'+b.dataset.view).classList.add('active');window.scrollTo({top:0,behavior:'smooth'})});
const lessons={scrum:'<b>Scrum view:</b> choose a small amount of valuable work for a short sprint, meet briefly to surface blockers, demonstrate the result, then improve the next sprint.',waterfall:'<b>Waterfall view:</b> agree requirements first and complete the project through planned phases. Changes are controlled because late changes can affect several completed stages.'};
function mode(m){document.querySelector('#modeLesson').innerHTML=lessons[m];document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x.dataset.mode===m))}document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>mode(b.dataset.mode));mode('scrum');
const cols=[['backlog','Backlog'],['sprint','Sprint ready'],['progress','In progress'],['done','Done']];
function renderBoard(){const board=document.querySelector('#taskBoard');board.innerHTML=cols.map(([key,label])=>`<div class="column"><div class="column-head"><b>${label}</b><span class="count">${state.tasks.filter(t=>t.status===key).length}</span></div>${state.tasks.filter(t=>t.status===key).map(t=>`<article class="task"><p>${t.title}</p><div class="task-meta"><span class="pill ${t.priority.toLowerCase()}">${t.priority}</span><span class="pill">${t.owner}</span><span class="pill">${t.due}</span></div><select aria-label="Move ${t.title}" onchange="moveTask(${t.id},this.value)">${cols.map(c=>`<option value="${c[0]}" ${t.status===c[0]?'selected':''}>Move to ${c[1]}</option>`).join('')}</select></article>`).join('')}</div>`).join('')}
window.moveTask=(id,status)=>{state.tasks.find(t=>t.id===id).status=status;save();toast('Task moved and progress updated')};
document.querySelector('#addTaskBtn').onclick=()=>document.querySelector('#taskDialog').showModal();document.querySelector('#taskForm').onsubmit=e=>{if(e.submitter.value==='cancel')return;const f=new FormData(e.target);state.tasks.push({id:Date.now(),title:f.get('title'),owner:f.get('owner'),priority:f.get('priority'),due:f.get('due'),status:'backlog'});e.target.reset();save();toast('Task added to backlog')};
function renderGantt(){const rows=[['Requirements and scope',1,2,''],['Form and sheet design',2,3,''],['Automation build',3,4,''],['Testing and fixes',4,5,''],['Launch milestone',6,6,'milestone']];document.querySelector('#gantt').innerHTML=`<div class="gantt-head"><div>Work package</div>${[1,2,3,4,5,6].map(w=>`<div>Week ${w}</div>`).join('')}</div>`+rows.map(r=>`<div class="gantt-row"><b>${r[0]}</b>${[1,2,3,4,5,6].map(w=>`<span>${w>=r[1]&&w<=r[2]?`<i class="bar ${r[3]}">${w===r[1]?r[0]:''}</i>`:''}</span>`).join('')}</div>`).join('')}
function scoreClass(s){return s>=15?'high':s>=8?'medium':''}function renderRisks(){document.querySelector('#riskTable').innerHTML=state.risks.map(r=>`<tr><td>${r.type}</td><td>${r.description}</td><td>${r.owner}</td><td><span class="score ${scoreClass(r.score)}">${r.score}</span></td><td>${r.response}</td><td>${r.status}</td></tr>`).join('')}
document.querySelector('#addRiskBtn').onclick=()=>document.querySelector('#riskDialog').showModal();document.querySelector('#riskForm').onsubmit=e=>{if(e.submitter.value==='cancel')return;const f=new FormData(e.target);state.risks.push({type:'Risk',description:f.get('description'),owner:'Aliza',score:Number(f.get('probability'))*Number(f.get('impact')),response:f.get('response'),status:'Open'});e.target.reset();save();toast('Risk logged')};
function renderBudget(){document.querySelector('#budgetTable').innerHTML=state.budget.map((b,i)=>`<tr><td>${b.name}</td><td>${money(b.base)}</td><td><input type="number" min="0" value="${b.actual}" onchange="budgetChange(${i},this.value)"></td><td>${money(b.base-b.actual)}</td></tr>`).join('');const base=state.budget.reduce((a,b)=>a+b.base,0),actual=state.budget.reduce((a,b)=>a+b.actual,0);document.querySelector('#budgetBase').textContent=money(base);document.querySelector('#budgetActual').textContent=money(actual);document.querySelector('#budgetVariance').textContent=money(base-actual)}window.budgetChange=(i,v)=>{state.budget[i].actual=Number(v);save()};
function renderChanges(){document.querySelector('#changeList').innerHTML=state.changes.map(c=>`<article class="change-card"><div><h3>${c.title}</h3><p>${c.reason}</p><small>Cost: ${money(c.cost)} · Schedule: ${c.schedule} · <b>${c.status}</b></small></div>${c.status==='Pending'?`<div class="decision"><button class="approve" onclick="decideChange(${c.id},'Approved')">Approve</button><button class="reject" onclick="decideChange(${c.id},'Rejected')">Reject</button></div>`:''}</article>`).join('')}window.decideChange=(id,status)=>{state.changes.find(c=>c.id===id).status=status;save();toast('Change '+status.toLowerCase())};document.querySelector('#addChangeBtn').onclick=()=>document.querySelector('#changeDialog').showModal();document.querySelector('#changeForm').onsubmit=e=>{if(e.submitter.value==='cancel')return;const f=new FormData(e.target);state.changes.push({id:Date.now(),title:f.get('title'),reason:f.get('reason'),cost:Number(f.get('cost')),schedule:f.get('schedule'),status:'Pending'});e.target.reset();save();toast('Change submitted for decision')};
function renderActions(){document.querySelector('#actionTable').innerHTML=state.actions.map((a,i)=>`<tr><td>${a.text}</td><td>${a.owner}</td><td>${a.due}</td><td><select onchange="actionChange(${i},this.value)"><option ${a.status==='Open'?'selected':''}>Open</option><option ${a.status==='Done'?'selected':''}>Done</option></select></td></tr>`).join('')}window.actionChange=(i,v)=>{state.actions[i].status=v;save()};document.querySelector('#addActionBtn').onclick=()=>{const text=prompt('Action to record:');if(text){state.actions.push({text,owner:'Aliza',due:'Next review',status:'Open'});save()}};
function metrics(){const done=state.tasks.filter(t=>t.status==='done').length,progress=Math.round(done/state.tasks.length*100),open=state.risks.filter(r=>r.status!=='Closed').length,base=state.budget.reduce((a,b)=>a+b.base,0),actual=state.budget.reduce((a,b)=>a+b.actual,0),used=Math.round(actual/base*100),critical=state.risks.some(r=>r.score>=15&&r.status!=='Closed');document.querySelector('#progressMetric').textContent=progress+'%';document.querySelector('#progressBar').style.width=progress+'%';document.querySelector('#riskMetric').textContent=open;document.querySelector('#budgetMetric').textContent=used+'%';const health=critical?'At risk':used>100?'Over budget':'On track';document.querySelector('#healthMetric').textContent=health;document.querySelector('#healthMetric').style.color=health==='On track'?'var(--green)':'var(--red)';document.querySelector('#healthReason').textContent=critical?'High-scoring issue needs action':used>100?'Actual cost exceeds baseline':'No critical blockers';return{progress,open,base,actual,health}}
function renderStatus(){const m=metrics(),done=state.tasks.filter(t=>t.status==='done').map(t=>t.title),next=state.tasks.filter(t=>t.status!=='done').slice(0,3).map(t=>t.title),high=state.risks.filter(r=>r.score>=15).map(r=>r.description),pending=state.changes.filter(c=>c.status==='Pending').map(c=>c.title);document.querySelector('#statusReport').innerHTML=`<div class="status-head"><div><h3>Expense Automation · Weekly Report</h3><small>Reporting date: 10 November 2026</small></div><span class="rag">${m.health.toUpperCase()}</span></div><div class="status-body"><section><h4>Overall progress</h4><p>${m.progress}% complete. ${state.tasks.filter(t=>t.status==='progress').length} task(s) currently in progress.</p></section><section><h4>Budget</h4><p>${money(m.actual)} used from ${money(m.base)} baseline.</p></section><section><h4>Completed</h4><ul>${(done.length?done:['No tasks completed yet']).map(x=>`<li>${x}</li>`).join('')}</ul></section><section><h4>Next priorities</h4><ul>${next.map(x=>`<li>${x}</li>`).join('')}</ul></section><section><h4>Risks and escalation</h4><ul>${(high.length?high:['No high risks']).map(x=>`<li>${x}</li>`).join('')}</ul></section><section><h4>Decisions required</h4><ul>${(pending.length?pending:['No pending change decisions']).map(x=>`<li>${x}</li>`).join('')}</ul></section></div>`}
document.querySelector('#copyStatusBtn').onclick=async()=>{await navigator.clipboard.writeText(document.querySelector('#statusReport').innerText);toast('Status report copied')};document.querySelector('#exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='expense-automation-project.json';a.click();URL.revokeObjectURL(a.href);toast('Project exported')};document.querySelector('#resetBtn').onclick=()=>{if(confirm('Reset all practice changes?')){state=structuredClone(initial);save();toast('Example reset')}};
function renderAll(){renderBoard();renderGantt();renderRisks();renderBudget();renderChanges();renderActions();renderStatus();metrics()}renderAll();
